/**
 * Unit tests for GaussNewtonOptimizer.doOptimize()
 */
public class GaussNewtonOptimizer_doOptimize_TriageGen0Test {

    /**
     * Mock class to extend GaussNewtonOptimizer since many methods are protected/internal
     */
    private static class TestableGaussNewtonOptimizer extends GaussNewtonOptimizer {
        private double[] target;
        private RealMatrix weight;
        private double[] startPoint;
        private MultiVariateJacobianFunction function;
        private boolean throwSingular = false;

        public TestableGaussNewtonOptimizer(boolean useLU, ConvergenceChecker<PointVectorValuePair> checker) {
            super(useLU, checker);
        }

        public void setTarget(double[] target) { this.target = target; }
        public void setWeight(RealMatrix weight) { this.weight = weight; }
        public void setStartPoint(double[] startPoint) { this.startPoint = startPoint; }
        public void setFunction(MultiVariateJacobianFunction function) { this.function = function; }
        public void setThrowSingular(boolean throwSingular) { this.throwSingular = throwSingular; }

        @Override
        protected void checkParameters() {
            if (target == null || weight == null || startPoint == null || function == null) {
                throw new IllegalArgumentException("Params missing");
            }
        }

        @Override
        protected double[] getTarget() { return target; }

        @Override
        protected RealMatrix getWeight() { return weight; }

        @Override
        protected double[] getStartPoint() { return startPoint; }

        @Override
        protected double[] computeObjectiveValue(double[] point) {
            return function.value(point);
        }

        @Override
        protected double[] computeResiduals(double[] objective) {
            double[] residuals = new double[objective.length];
            for (int i = 0; i < objective.length; i++) {
                residuals[i] = objective[i] - target[i];
            }
            return residuals;
        }

        @Override
        protected RealMatrix computeWeightedJacobian(double[] point) {
            // For simplicity in testing, we return a Jacobian that ignores weights here 
            // because the code multiplies weight * grad inside the loop.
            // We return a matrix where entries are 1.0 for simplicity.
            return function.jacobian(point);
        }

        @Override
        protected double computeCost(double[] residuals) {
            double sum = 0;
            for (double r : residuals) sum += r * r;
            return sum;
        }
    }

    @Test(expected = NullArgumentException.class)
    public void testDoOptimize_NullChecker() {
        new GaussNewtonOptimizer(null).doOptimize();
    }

    @Test
    public void testDoOptimize_Success_LU() {
        ConvergenceChecker<PointVectorValuePair> checker = mock(ConvergenceChecker.class);
        when(checker.converged(anyInt(), any(), any())).thenReturn(false, true);

        TestableGaussNewtonOptimizer optimizer = new TestableGaussNewtonOptimizer(true, checker);

        double[] target = {1.0, 2.0};
        double[] start = {0.0, 0.0};
        double[][] weightData = {{1.0, 0.0}, {0.0, 1.0}};

        optimizer.setTarget(target);
        optimizer.setStartPoint(start);
        optimizer.setWeight(org.apache.commons.math3.linear.MatrixUtils.createRealMatrix(weightData));

        // Mock function: f(x) = x. Jacobian = I.
        MultiVariateJacobianFunction function = point -> {
            double[] val = new double[]{point[0], point[1]};
            double[][] jac = {{1.0, 0.0}, {0.0, 1.0}};
            return new org.apache.commons.math3.optim.nonlinear.vector.jacobian.MultiVariateJacobianFunction() {
                @Override public double[] value(double[] p) { return val; }
                @Override public RealMatrix jacobian(double[] p) { return org.apache.commons.math3.linear.MatrixUtils.createRealMatrix(jac); }
            };
        };
        // Since we can't easily mock the anonymous class, we use a concrete implementation
        optimizer.setFunction(new MultiVariateJacobianFunction() {
            @Override public double[] value(double[] p) { return new double[]{p[0], p[1]}; }
            @Override public RealMatrix jacobian(double[] p) { 
                return org.apache.commons.math3.linear.MatrixUtils.createRealIdentityMatrix(2); 
            }
        });

        PointVectorValuePair result = optimizer.doOptimize();
        assertNotNull(result);
        verify(checker, atLeastOnce()).converged(anyInt(), any(), any());
    }

    @Test
    public void testDoOptimize_Success_QR() {
        ConvergenceChecker<PointVectorValuePair> checker = mock(ConvergenceChecker.class);
        when(checker.converged(anyInt(), any(), any())).thenReturn(false, true);

        TestableGaussNewtonOptimizer optimizer = new TestableGaussNewtonOptimizer(false, checker);

        optimizer.setTarget(new double[]{1.0, 1.0});
        optimizer.setStartPoint(new double[]{0.0, 0.0});
        optimizer.setWeight(org.apache.commons.math3.linear.MatrixUtils.createRealIdentityMatrix(2));
        optimizer.setFunction(new MultiVariateJacobianFunction() {
            @Override public double[] value(double[] p) { return new double[]{p[0], p[1]}; }
            @Override public RealMatrix jacobian(double[] p) { return org.apache.commons.math3.linear.MatrixUtils.createRealIdentityMatrix(2); }
        });

        PointVectorValuePair result = optimizer.doOptimize();
        assertNotNull(result);
    }

    @Test(expected = org.apache.commons.math3.exception.ConvergenceException.class)
    public void testDoOptimize_SingularMatrix() {
        ConvergenceChecker<PointVectorValuePair> checker = mock(ConvergenceChecker.class);
        when(checker.converged(anyInt(), any(), any())).thenReturn(false);

        TestableGaussNewtonOptimizer optimizer = new TestableGaussNewtonOptimizer(true, checker);

        optimizer.setTarget(new double[]{1.0, 1.0});
        optimizer.setStartPoint(new double[]{0.0, 0.0});
        optimizer.setWeight(org.apache.commons.math3.linear.MatrixUtils.createRealIdentityMatrix(2));

        // Jacobian of all zeros makes matrix A singular
        optimizer.setFunction(new MultiVariateJacobianFunction() {
            @Override public double[] value(double[] p) { return new double[]{0.0, 0.0}; }
            @Override public RealMatrix jacobian(double[] p) { return org.apache.commons.math3.linear.MatrixUtils.createRealMatrix(2, 2); }
        });

        optimizer.doOptimize();
    }
}
